with filtered as (select id, product_id, unit_price, round(quantity / unit_price, 2) as line_total, case when unit_price >= 330 then 'High' when unit_price >= 80 then 'Medium' else 'Low' end as unit_price_band from order_items where product_id is null), with_dims as (select e.*, d.launch_date, d.product_name, d.cost from filtered e left join products d on e.product_id = d.id), ranked as (select * from (select *, row_number() over (partition by product_id order by launch_date desc nulls first, id) as row_num from with_dims) ranked where row_num = 1), enriched as (select src.*, d.launch_date as product_launch_date from ranked src left join products d on src.product_id = d.id), deduped as (select *, row_number() over (partition by product_id order by launch_date desc nulls last, id) as rn from enriched qualify rn = 1) select product_id, date_trunc('year', product_launch_date) as year_start, approx_percentile(line_total, array(0.25, 0.5, 0.75)) as line_total_quartiles, count(distinct id) as distinct_ids, count(*) as row_count, stddev_samp(unit_price) as unit_price_stddev, approx_percentile(unit_price, array(0.25, 0.5, 0.75)) as unit_price_quartiles, grouping(product_id) as grouping_level from deduped group by grouping sets ((product_id, date_trunc('year', product_launch_date)), (product_id), ()) order by year_start desc nulls last
